    let ret = unsafe { libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), set) };
    if ret == 0 {
        log::info!("restore_affinity: mask={}", affinity_summary(set));
    } else {
        log::warn!("restore_affinity: sched_setaffinity failed");
    }
}

